<div class="check-row"><span><?=e(t('Nouveaux contenus / existants conservés','New content / existing preserved'))?></span><strong><?=$report['imported']?> / <?=$report['duplicates']?></strong></div><div class="check-row"><span><?=e(t('Collisions de slugs résolues','Resolved slug collisions'))?></span><strong><?=$report['collisions']?></strong></div><div class="check-row"><span><?=e(t('Médias nouveaux / réutilisés','New / reused media'))?></span><strong><?=$report['media_imported']?> / <?=$report['media_reused']?></strong></div>
